import type { Metadata } from "next";
import Link from "next/link";
import { ArrowUpRight, BellRing, ClipboardList, Package, Store } from "lucide-react";
import { createServerSupabase } from "@/lib/supabase/server";
import { money } from "@/lib/money";
import { SignChip } from "@/components/ui/Brand";
import ActivationButton from "@/components/ActivationButton";
import CopyTextButton from "@/components/CopyTextButton";
export const metadata:Metadata={title:"Your shop"};
export default async function VendorHome(){const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return <div className="p-8">Please log in.</div>;const {data:vendor}=await supabase.from("vendors").select("id,business_name,slug,is_active,accepting_orders").eq("owner_id",user.id).maybeSingle();if(!vendor)return <div className="container py-12"><h1 className="display text-3xl font-bold">Finish setting up your shop</h1><p className="muted mt-2">Your business profile could not be found.</p></div>;const [ordersRes,productsRes]=await Promise.all([supabase.from("orders").select("id,total_amount,vendor_amount,payment_status,created_at",{count:"exact"}).eq("vendor_id",vendor.id),supabase.from("products").select("id",{count:"exact",head:true}).eq("vendor_id",vendor.id)]);const orders=ordersRes.data||[];const paid=orders.filter(o=>o.payment_status==="SUCCESS");const sales=paid.reduce((n,o)=>n+Number(o.vendor_amount||0),0);const week=Date.now()-7*86400000;const paidWeek=paid.filter(o=>new Date(o.created_at).getTime()>=week).length;const pendingOrders=orders.filter(o=>o.payment_status==="PENDING").length;const trendDays=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(6-i));const key=d.toLocaleDateString("en-CA");const amount=paid.filter(o=>new Date(o.created_at).toLocaleDateString("en-CA")===key).reduce((n,o)=>n+Number(o.vendor_amount||0),0);return {key,label:d.toLocaleDateString("en-GH",{weekday:"short"}),amount};});const trendMax=Math.max(1,...trendDays.map(d=>d.amount));const hasSalesData=trendDays.some(d=>d.amount>0);const chartMoney=(value:number)=>value>=1000?`GH₵ ${(value/1000).toLocaleString("en-GH",{maximumFractionDigits:1})}k`:money(value);const chartX=(index:number)=>600*(index+0.5)/7;const chartY=(amount:number)=>52-(amount/trendMax)*42;const trendPoints=trendDays.map((d,i)=>`${chartX(i)},${chartY(d.amount)}`).join(" ");const recent=[...orders].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5);return <main className="min-h-screen sp-dashboard sp-dashboard--vendor"><header className="bg-[#0E3B2C] text-white"><div className="container py-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="text-sm text-[#CFE9DB]">Your shop</p><h1 className="display mt-1 text-3xl font-bold">{vendor.business_name}</h1><p className="mt-2 flex items-center gap-2 text-sm"><span className={`h-2.5 w-2.5 rounded-full ${vendor.accepting_orders&&vendor.is_active?"bg-[#1FAA63]":"bg-[#FFC83D]"}`}/>{vendor.is_active?(vendor.accepting_orders?"Open":"Paused"):"Not live yet"}</p></div><a className="btn gold" href={`/store/${vendor.slug}`} target="_blank" rel="noreferrer">Open my shop <ArrowUpRight size={18}/></a></div><div className="mt-5"><SignChip slug={vendor.slug}/></div></div></header><div className="container py-6">{!vendor.is_active&&<div className="ticket mb-6"><p className="text-sm font-bold">One step left</p><h2 className="display mt-1 text-3xl font-bold">Pay GH₵ 150 to go live</h2><p className="mt-2">Once payment clears, customers can place orders from your shop link.</p><ActivationButton/></div>}<div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[["Verified sales",money(sales)],["Total orders",String(ordersRes.count||0)],["Pending orders",String(pendingOrders)],["Paid this week",String(paidWeek)],["Products",String(productsRes.count||0)]].map(([label,value])=><div className="kpi" key={label}><p className="muted text-sm">{label}</p><p className="display mt-2 text-2xl font-bold sm:text-3xl">{value}</p></div>)}</div><div className="sp-vendor-analytics mt-6 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><section className="card sp-revenue-card p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="muted text-xs font-bold uppercase tracking-[.13em]">Sales activity</p><h2 className="display mt-1 text-2xl font-bold">Last 7 days</h2><p className="muted mt-1 text-sm">Successful payments, based on your order history</p></div><span className="sp-chart-key"><i/> Verified sales</span></div><div className={`sp-revenue-chart mt-5 ${hasSalesData?"":"sp-revenue-chart--empty"}`}>
  <div className="sp-chart-ylabels" aria-hidden="true"><span>{hasSalesData?chartMoney(trendMax):"—"}</span><span>{hasSalesData?chartMoney(trendMax/2):"—"}</span><span>GH₵ 0</span></div>
  <div className="min-w-0 flex-1">
    <div className="sp-chart-plot">
      <svg viewBox="0 0 600 60" preserveAspectRatio="none" role="img" aria-label={hasSalesData?`Verified sales over the last seven days. Highest daily scale ${chartMoney(trendMax)}.`:"No verified sales have been recorded in the last seven days."}>
        <defs><linearGradient id="spRevenueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#1b8055" stopOpacity=".22"/><stop offset="100%" stopColor="#1b8055" stopOpacity="0"/></linearGradient></defs>
        <g className="sp-chart-grid" aria-hidden="true"><line x1="0" y1="10" x2="600" y2="10"/><line x1="0" y1="31" x2="600" y2="31"/><line x1="0" y1="52" x2="600" y2="52"/></g>
        {hasSalesData?<>
        <path d={`M ${trendDays.map((d,i)=>`${chartX(i)},${chartY(d.amount)}`).join(' L ')} L ${chartX(6)},60 L ${chartX(0)},60 Z`} fill="url(#spRevenueFill)"/>
        <polyline points={trendPoints} fill="none" stroke="#16845b" strokeWidth="2.5" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round"/>
        {trendDays.map((d,i)=><circle key={d.key} cx={chartX(i)} cy={chartY(d.amount)} r="2.8" fill="#fff" stroke="#16845b" strokeWidth="2" vectorEffect="non-scaling-stroke"/>)}
        </>:null}
      </svg>
      {!hasSalesData&&<span className="sp-chart-empty-label">No sales recorded this week</span>}
    </div>
    <div className="sp-chart-xlabels">{trendDays.map(d=><span key={d.key}>{d.label}</span>)}</div>
    <ul className="sr-only" aria-label="Daily verified sales">{trendDays.map(d=><li key={d.key}>{d.key}: {money(d.amount)}</li>)}</ul>
  </div>
</div></section><section className="card sp-action-card p-5 sm:p-6"><p className="muted text-xs font-bold uppercase tracking-[.13em]">Keep momentum</p><h2 className="display mt-1 text-2xl font-bold">Your next steps</h2><p className="muted mt-2 text-sm">A few quick ways to keep your shop ready for customers.</p><div className="mt-5 grid gap-2"><Link className="sp-quick-action" href="/dashboard/vendor/orders"><span className="sp-quick-icon"><ClipboardList size={18}/></span><span><b>Review orders</b><small>{pendingOrders?`${pendingOrders} awaiting payment`:'Keep up with new orders'}</small></span><ArrowUpRight size={17}/></Link><Link className="sp-quick-action" href="/dashboard/vendor/products"><span className="sp-quick-icon"><Package size={18}/></span><span><b>Manage products</b><small>Keep your catalogue fresh</small></span><ArrowUpRight size={17}/></Link></div></section></div><div className="mt-6 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="card p-5"><div className="flex items-center justify-between"><h2 className="display text-2xl font-bold">Recent orders</h2><Link className="text-sm font-bold underline" href="/dashboard/vendor/orders">View all</Link></div>{recent.length===0?<div className="py-12 text-center"><BellRing className="mx-auto text-[#4B5F55]" size={34}/><p className="mt-3 font-bold">Your orders will show up here</p><p className="muted mt-1 text-sm">Share your shop link to welcome your first customer.</p></div>:<div className="mt-3 divide-y divide-[var(--line)]">{recent.map(o=><div key={o.id} className="flex items-center justify-between gap-3 py-4"><div><p className="font-semibold">{money(Number(o.total_amount))}</p><p className="muted mt-1 text-xs">{new Date(o.created_at).toLocaleString("en-GH")}</p></div><span className={`status ${o.payment_status==="SUCCESS"?"success":o.payment_status==="PENDING"?"pending":"error"}`}>{o.payment_status}</span></div>)}</div>}</section><aside className="card p-5"><h2 className="display text-2xl font-bold">Get your shop ready</h2><div className="mt-4 space-y-3"><p className="flex gap-3"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#CFE9DB]"><Package size={17}/></span><span><b>Add a product</b><br/><Link className="text-sm underline" href="/dashboard/vendor/products">Add your first item</Link></span></p><p className="flex gap-3"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#CFE9DB]"><Store size={17}/></span><span><b>Review your storefront</b><br/><Link className="text-sm underline" href="/dashboard/vendor/storefront">Add your story and banner</Link></span></p><p className="flex gap-3"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#CFE9DB]"><ClipboardList size={17}/></span><span><b>Share your shop link</b><br/><CopyTextButton value={`https://${process.env.NEXT_PUBLIC_ROOT_DOMAIN||"seepay.shop"}/store/${vendor.slug}`} label="Copy shop link"/></span></p></div></aside></div></div><footer className="container py-6 text-sm muted"><Link href="/terms" className="underline">Terms</Link> · <Link href="/privacy" className="underline">Privacy</Link></footer></main>}
